-- Migration 24: group lives (guests on stage). Additive and re-runnable; no existing data is rewritten.
--
-- 1. live_guests: who the host has invited on stage for a stream (at most 3 besides the host). Only the host changes it
--    (live_guest_set), a guest can step down (live_guest_leave), and the guest list is readable by the host and by the guest.
-- 2. live_token_gate: identical rules, plus role 'guest' for someone on stage, so a guest who reconnects keeps the right to
--    send camera and microphone (the Edge Function grants exactly those two sources; never screen share).
-- 3. ban_from_stream also takes a banned person off stage.
--
-- Rollback: drop table public.live_guests; drop function public.live_guest_set(uuid, uuid, boolean),
-- public.live_guest_leave(uuid); re-run live_token_gate and ban_from_stream from migration 7.

create table if not exists public.live_guests (
  stream_id uuid not null references public.live_streams(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (stream_id, user_id)
);
create index if not exists live_guests_user_idx on public.live_guests (user_id);
alter table public.live_guests enable row level security;
revoke all on public.live_guests from anon, authenticated;
grant select on public.live_guests to authenticated;
drop policy if exists live_guests_read on public.live_guests;
create policy live_guests_read on public.live_guests for select to authenticated
  using (user_id = (select auth.uid()) or exists (select 1 from public.live_streams s where s.id = stream_id and s.host = (select auth.uid())));

-- Host only: put someone on stage or take them off.
create or replace function public.live_guest_set(sid uuid, target uuid, on_stage boolean) returns integer
language plpgsql security definer set search_path = '' as $$
declare s public.live_streams; n integer;
begin
  select * into s from public.live_streams where id = sid;
  if not found or s.host is distinct from auth.uid() then raise exception 'Only the host can do that' using errcode = '42501'; end if;
  if target = s.host then raise exception 'You are already on stage'; end if;
  if on_stage then
    if s.status not in ('scheduled', 'live') then raise exception 'This stream has ended'; end if;
    if exists (select 1 from public.live_bans b where b.stream_id = sid and b.user_id = target) then raise exception 'That person was removed from this stream'; end if;
    if public.is_blocked(s.host, target) then raise exception 'You can’t invite this person'; end if;
    select count(*) into n from public.live_guests where stream_id = sid;
    if n >= 3 and not exists (select 1 from public.live_guests where stream_id = sid and user_id = target) then raise exception 'Up to 3 guests can be on stage'; end if;
    insert into public.live_guests (stream_id, user_id) values (sid, target) on conflict do nothing;
  else
    delete from public.live_guests where stream_id = sid and user_id = target;
  end if;
  select count(*) into n from public.live_guests where stream_id = sid;
  return n;
end $$;

-- A guest steps down themselves.
create or replace function public.live_guest_leave(sid uuid) returns void
language sql security definer set search_path = '' as $$
  delete from public.live_guests where stream_id = sid and user_id = auth.uid();
$$;

-- Migration 7's rules, unchanged, plus the 'guest' role for someone the host put on stage.
create or replace function public.live_token_gate(sid uuid, want_publish boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare s public.live_streams; p public.profiles; recent integer; is_host boolean; is_guest boolean;
begin
  if auth.uid() is null then raise exception 'Sign in to watch' using errcode = '28000'; end if;
  select * into s from public.live_streams where id = sid;
  if not found then raise exception 'Stream not found'; end if;
  select * into p from public.profiles where id = auth.uid();
  is_host := s.host = auth.uid();
  if want_publish and not is_host then raise exception 'Only the host can broadcast'; end if;
  if want_publish and s.status not in ('scheduled','live') then raise exception 'This stream has ended'; end if;
  if not want_publish and not public.can_watch_stream(sid) then
    raise exception '%', case when s.access = 'ticket' and s.status in ('scheduled','live') then 'You need a ticket for this event to watch' else 'This stream is not available' end;
  end if;
  is_guest := not is_host and s.status in ('scheduled','live')
    and exists (select 1 from public.live_guests g where g.stream_id = sid and g.user_id = auth.uid())
    and not exists (select 1 from public.live_bans b where b.stream_id = sid and b.user_id = auth.uid());
  select count(*) into recent from public.live_access_log where user_id = auth.uid() and created_at > now() - interval '1 minute';
  if recent >= 20 then raise exception 'Too many attempts. Please wait a moment.'; end if;
  insert into public.live_access_log (user_id, stream_id, role) values (auth.uid(), sid, case when want_publish then 'host' else 'viewer' end);
  delete from public.live_access_log where created_at < now() - interval '2 days' and id % 50 = 0;     -- cheap housekeeping
  return jsonb_build_object('room', s.room, 'title', s.title, 'status', s.status,
                            'role', case when want_publish then 'host' when is_guest then 'guest' else 'viewer' end,
                            'name', coalesce(nullif(p.display_name, ''), p.username), 'host', s.host, 'recording_consent', s.recording_consent);
end $$;

create or replace function public.ban_from_stream(sid uuid, target uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.live_streams where id = sid and host = auth.uid()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if target = auth.uid() then raise exception 'You cannot remove yourself'; end if;
  insert into public.live_bans (stream_id, user_id) values (sid, target) on conflict do nothing;
  delete from public.live_guests where stream_id = sid and user_id = target;
end $$;

revoke execute on function public.live_guest_set(uuid, uuid, boolean), public.live_guest_leave(uuid), public.live_token_gate(uuid, boolean), public.ban_from_stream(uuid, uuid) from public, anon;
grant execute on function public.live_guest_set(uuid, uuid, boolean), public.live_guest_leave(uuid), public.live_token_gate(uuid, boolean), public.ban_from_stream(uuid, uuid) to authenticated;

commit;

select item, ok from (values
  ('guest list table (host and guest can read; nobody writes directly)', to_regclass('public.live_guests') is not null and not has_table_privilege('authenticated', 'public.live_guests', 'insert')),
  ('host-only stage control', exists (select 1 from pg_proc where proname = 'live_guest_set') and exists (select 1 from pg_proc where proname = 'live_guest_leave')),
  ('token gate knows guests', (select prosrc from pg_proc where proname = 'live_token_gate') like '%guest%')
) as v(item, ok);
